solution.solution.cpp:
int daysInMonth(int month, bool leapYear)
{
    switch (month)
    {
    case 1: case 3: case 5: case 7: case 8: case 10: case 12:
        return 31;
    case 4: case 6: case 9: case 11:
        return 30;
    case 2:
        return leapYear ? 29 : 28;
    default:
        return -1;
    }
}

unitTests:
TEST("31-day months") { for (int m : { 1, 3, 5, 7, 8, 10, 12 }) CHECK_EQ(daysInMonth(m, false), 31); }
TEST("30-day months") { for (int m : { 4, 6, 9, 11 }) CHECK_EQ(daysInMonth(m, true), 30); }
TEST("February") { CHECK_EQ(daysInMonth(2, false), 28); CHECK_EQ(daysInMonth(2, true), 29); }
TEST("months that do not exist") { CHECK_EQ(daysInMonth(0, false), -1); CHECK_EQ(daysInMonth(13, true), -1); CHECK_EQ(daysInMonth(-4, false), -1); }

